// ---------- diagrams (SmartArt-like) and real screenshots ----------
function addCircle(parent, cx, cy, d, fill, stroke) {
  const e = figma.createEllipse();
  parent.appendChild(e);
  e.resize(d, d);
  e.fills = fill ? [solid(fill)] : [];
  if (stroke) { e.strokes = [solid(stroke)]; e.strokeWeight = 2; e.dashPattern = [10, 8]; }
  e.x = cx - d / 2; e.y = cy - d / 2;
  return e;
}
function addLine(parent, x1, y1, x2, y2, color, weight) {
  const v = figma.createVector();
  parent.appendChild(v);
  const x = Math.min(x1, x2), y = Math.min(y1, y2);
  v.vectorPaths = [{ windingRule: "NONE", data: `M ${x1 - x} ${y1 - y} L ${x2 - x} ${y2 - y}` }];
  v.strokes = [solid(color)];
  v.strokeWeight = weight || 3;
  v.x = x; v.y = y;
  return v;
}
const SHADOW = [{ type: "DROP_SHADOW", color: { r: 0.06, g: 0.09, b: 0.16, a: 0.16 }, offset: { x: 0, y: 12 }, radius: 32, spread: 0, visible: true, blendMode: "NORMAL" }];
// A screenshot (images at the end of this file) in a rounded frame.
function addImage(parent, key, x, y, w, h, radius) {
  const r = figma.createRectangle();
  parent.appendChild(r);
  r.resize(w, h);
  r.fills = [{ type: "IMAGE", scaleMode: "FILL", imageHash: figma.createImage(figma.base64Decode(IMAGES[key])).hash }];
  if (radius) r.cornerRadius = radius;
  r.x = x; r.y = y;
  return r;
}
// Centred text in a box of width w.
function addCentered(parent, font, size, color, chars, x, y, w, lh) {
  const t = addText(parent, font, size, color, chars, x, y, w, lh ? { lh } : undefined);
  t.textAlignHorizontal = "CENTER";
  return t;
}

