// Section numbers in the defense order ("ҚОСЫМША" for backup slides).
async function relabel(slide, prefix) {
  const t = texts(slide).find((n) => /^(\d\d|ҚОСЫМША) · /.test(n.characters));
  if (!t) return;
  const cur = t.characters.split(" · ")[0];
  if (cur !== prefix) { await sub(t, cur + " · ", prefix + " · "); ok(`подпись: ${cur} → ${prefix}`); }
}

